"use client";

/**
 * Glyph decode: a line resolves out of scrambled glyphs from left to right.
 * Each letter flashes the primary colour as it locks, then cools to ink, and
 * an optional product name lands underneath.
 *
 * Written by Better Design. Painted from the theme prop, so the settled line
 * takes the product's ink and the decoding front takes its primary colour.
 */
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadMono } from "@remotion/google-fonts/JetBrainsMono";
import { AbsoluteFill, random, useCurrentFrame } from "remotion";
import { easings, pickFont, progress, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: MONO } = loadMono("normal", { weights: ["500", "700"], subsets: ["latin"] });
const { fontFamily: INTER } = loadInter("normal", { weights: ["600"], subsets: ["latin"] });

export interface GlyphDecodeProps {
  /** The line that decodes. */
  text?: string;
  /** A name that lands under the line once it has resolved. Leave empty to skip it. */
  name?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded, used for the line. Defaults to the theme's face, then JetBrains Mono. */
  font?: string;
}

const GLYPHS = "ABCDEFGHJKLMNPQRSTUVWXYZ0123456789#%&*+=/<>?";
const SCRAMBLE_AT = 4;
const SCRAMBLE_GAP = 0.7;
const RESOLVE_AT = 18;
const RESOLVE_GAP = 1.9;
const FLASH_FRAMES = 16;
/** Frames between two glyph swaps while a letter is still scrambled. */
const FLICKER = 2;

/** A line that decodes out of noise, then a name that lands under it. */
export function GlyphDecode({
  text = "Your product, in motion",
  name = "Your product",
  theme: themeOverride,
  font,
}: GlyphDecodeProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, MONO);
  const chars = Array.from(text);
  const size = Math.min(120, Math.round(1680 / (Math.max(1, chars.length) * 0.6)));
  const doneAt = RESOLVE_AT + chars.length * RESOLVE_GAP + FLASH_FRAMES;
  const nameT = easings.out(progress(frame, doneAt - 4, 22));

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center" }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.5 }}>
        <div style={{ fontFamily: family, fontSize: size, fontWeight: 700, letterSpacing: "-0.02em", lineHeight: 1.1, whiteSpace: "pre" }}>
          {chars.map((ch, i) => {
            const shownAt = SCRAMBLE_AT + i * SCRAMBLE_GAP;
            const resolveAt = RESOLVE_AT + i * RESOLVE_GAP;
            if (ch === " ") return <span key={i}> </span>;
            if (frame < shownAt) return <span key={i} style={{ opacity: 0 }}>{ch}</span>;
            if (frame < resolveAt) {
              const tick = Math.floor(frame / FLICKER);
              const glyph = GLYPHS[Math.floor(random(`glyph-${i}-${tick}`) * GLYPHS.length)];
              const fade = easings.out(progress(frame, shownAt, 6));
              // Letters near the front glow brighter, so the decode reads as a moving edge.
              const near = 1 - Math.min(1, (resolveAt - frame) / 18);
              return (
                <span key={i} style={{ position: "relative", display: "inline-block", width: "0.6em", textAlign: "center", opacity: fade * (0.3 + near * 0.6) }}>
                  <span style={{ color: theme.mutedForeground, opacity: 1 - near }}>{glyph}</span>
                  <span style={{ position: "absolute", left: 0, right: 0, top: 0, color: theme.primary, opacity: near }}>{glyph}</span>
                </span>
              );
            }
            const cool = easings.out(progress(frame, resolveAt, FLASH_FRAMES));
            const pop = 1 - easings.out(progress(frame, resolveAt, 8));
            return (
              <span
                key={i}
                style={{
                  display: "inline-block",
                  width: "0.6em",
                  textAlign: "center",
                  position: "relative",
                  color: theme.foreground,
                  textShadow: `0 0 ${size * 0.3 * (1 - cool)}px ${withAlpha(theme.primary, 0.6 * (1 - cool))}`,
                  transform: `translateY(${-pop * 0.06}em)`,
                }}
              >
                <span style={{ opacity: cool }}>{ch}</span>
                <span style={{ position: "absolute", left: 0, right: 0, top: 0, color: theme.primary, opacity: 1 - cool }}>{ch}</span>
              </span>
            );
          })}
        </div>
        {name ? (
          <div
            style={{
              fontFamily: pickFont(undefined, theme, INTER),
              fontSize: Math.max(40, Math.round(size * 0.46)),
              fontWeight: 600,
              letterSpacing: `${0.02 + (1 - nameT) * 0.18}em`,
              color: theme.mutedForeground,
              opacity: nameT,
              transform: `translateY(${(1 - nameT) * 18}px)`,
              display: "flex",
              alignItems: "center",
              gap: size * 0.18,
            }}
          >
            <span style={{ width: size * 0.14, height: size * 0.14, borderRadius: "50%", background: theme.primary }} />
            {name}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
}
